-- Gerado por dados/ETL/tratamento.py - não editar à mão
-- Carga completa de alimentos (TACO e IBGE, valores por 1 g, mesmo padrão do banco),
-- medidas caseiras (IBGE/POF 2008-2009 e tabela da UFG) e dietas-modelo.
-- medidas_fonte: IBGE | IBGE_REF_TACO | MAPEADO | REFERENCIA_EXTERNA | ESTIMADO (valores aproximados)
-- Rode DEPOIS de subir o backend uma vez (ele cria as tabelas). Pode rodar de novo sem duplicar.

USE fittnutri;

-- 1) Colunas novas: gramas de 1 unidade de cada medida do front + origem das medidas
--    (cada uma só é criada se ainda não existir)
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE alimentos ADD COLUMN gramas_unidade DOUBLE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'alimentos' AND COLUMN_NAME = 'gramas_unidade');
PREPARE passo FROM @sql; EXECUTE passo; DEALLOCATE PREPARE passo;
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE alimentos ADD COLUMN gramas_colher_sopa DOUBLE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'alimentos' AND COLUMN_NAME = 'gramas_colher_sopa');
PREPARE passo FROM @sql; EXECUTE passo; DEALLOCATE PREPARE passo;
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE alimentos ADD COLUMN gramas_colher_cha DOUBLE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'alimentos' AND COLUMN_NAME = 'gramas_colher_cha');
PREPARE passo FROM @sql; EXECUTE passo; DEALLOCATE PREPARE passo;
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE alimentos ADD COLUMN gramas_xicara DOUBLE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'alimentos' AND COLUMN_NAME = 'gramas_xicara');
PREPARE passo FROM @sql; EXECUTE passo; DEALLOCATE PREPARE passo;
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE alimentos ADD COLUMN gramas_ml DOUBLE NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'alimentos' AND COLUMN_NAME = 'gramas_ml');
PREPARE passo FROM @sql; EXECUTE passo; DEALLOCATE PREPARE passo;
SET @sql = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE alimentos ADD COLUMN medidas_fonte VARCHAR(20) NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'alimentos' AND COLUMN_NAME = 'medidas_fonte');
PREPARE passo FROM @sql; EXECUTE passo; DEALLOCATE PREPARE passo;

